<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Rest;use Atlas\Platform\Core\Logging\Logger;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\Workflows\Authoring\WorkflowDraftService;use InvalidArgumentException;use Throwable;final class WorkflowDraftController{public function __construct(private WorkflowDraftService$service,private CurrentOrganizationResolver$organizations,private Logger$logger){}public function permission():bool{return current_user_can('atlas_manage_workflows');}public function create(\WP_REST_Request$request):\WP_REST_Response|\WP_Error{$user=get_current_user_id();$organization=$this->organizations->resolveForUser($user);try{$result=$this->service->create(sanitize_text_field((string)$request->get_header('Idempotency-Key')),(array)$request->get_json_params(),$organization?->id??'',$user,current_user_can('atlas_manage_atlas'));return new \WP_REST_Response($result,$result['replayed']?200:201);}catch(InvalidArgumentException$failure){return new \WP_Error('atlas_invalid_workflow_draft',$failure->getMessage(),['status'=>400]);}catch(Throwable$failure){$conflict=str_contains($failure->getMessage(),'different request');$this->logger->log($conflict?'warning':'error','workflows.draft_failed','Workflow draft creation did not complete.',['module'=>'workflows','exception'=>$failure]);return new \WP_Error('atlas_workflow_draft_failed',$conflict?$failure->getMessage():'Workflow draft creation failed safely.',['status'=>$conflict?409:500]);}}}
